/**
 * Copies the kit models/textures the town needs into `public/assets` so the
 * Next.js app can serve them.
 *
 * The GLB files are already part of this repository, so the copy is intentionally
 * git-ignored (see .gitignore) and regenerated by `npm run assets:sync`, which
 * also runs automatically before `npm run dev` / `npm run build`.
 *
 *   node scripts/sync-assets.mjs [--all]
 */
import fs from "node:fs";
import path from "node:path";
import { REPO_ROOT, PACK_DIRS, PACK_TEXTURE_DIRS } from "./lib/paths.mjs";

const OUT = path.join(REPO_ROOT, "public", "assets", "models");
const ALL = process.argv.includes("--all");

/** Models the layout actually references; --all copies every kit model. */
function neededModels() {
  const files = ["town.ts", "buildings.ts", "props.ts", "rides.ts", "palette.ts"].map((f) => path.join(REPO_ROOT, "src/game/layout", f));
  const keys = new Set();
  for (const file of files) {
    const src = fs.readFileSync(file, "utf8");
    for (const m of src.matchAll(/["'](urban|td|mini)\/([a-z0-9\-_]+)["']/g)) keys.add(`${m[1]}/${m[2]}`);
    if (path.basename(file) !== "town.ts") continue;
    // town.ts also references the animated character strips by full key
    for (const m of src.matchAll(/["'](mini|urban)\/(character|wheelchair|aid)[a-z0-9\-_]*["']/g)) keys.add(m[0].replace(/["']/g, ""));
  }
  return keys;
}

function copyIfChanged(from, to) {
  const stat = fs.statSync(from);
  if (fs.existsSync(to) && fs.statSync(to).size === stat.size && fs.statSync(to).mtimeMs >= stat.mtimeMs) return false;
  fs.mkdirSync(path.dirname(to), { recursive: true });
  fs.copyFileSync(from, to);
  return true;
}

const needed = neededModels();
let copied = 0;
let skipped = 0;
const missing = [];

for (const [pack, dir] of Object.entries(PACK_DIRS)) {
  const abs = path.join(REPO_ROOT, dir);
  const texAbs = path.join(REPO_ROOT, PACK_TEXTURE_DIRS[pack]);
  const models = fs.readdirSync(abs).filter((f) => f.endsWith(".glb"));
  for (const file of models) {
    const key = `${pack}/${path.basename(file, ".glb")}`;
    if (!ALL && !needed.has(key)) {
      skipped++;
      continue;
    }
    copyIfChanged(path.join(abs, file), path.join(OUT, pack, file)) ? copied++ : skipped++;
  }
  if (!fs.existsSync(texAbs)) continue;
  for (const tex of fs.readdirSync(texAbs)) {
    // every pack keeps its textures next to the models, referenced as
    // "Textures/<name>.png" inside the GLB, so mirror that layout
    copyIfChanged(path.join(texAbs, tex), path.join(OUT, pack, "Textures", tex)) ? copied++ : skipped++;
  }
}

// A key referenced by the layout must be either a kit model or a kit texture.
const available = new Set();
const textures = new Set();
for (const [pack, dir] of Object.entries(PACK_DIRS)) {
  for (const f of fs.readdirSync(path.join(REPO_ROOT, dir))) {
    if (f.endsWith(".glb")) available.add(`${pack}/${path.basename(f, ".glb")}`);
  }
  const texDir = path.join(REPO_ROOT, PACK_TEXTURE_DIRS[pack]);
  if (!fs.existsSync(texDir)) continue;
  for (const f of fs.readdirSync(texDir)) textures.add(`${pack}/${path.basename(f, ".png")}`);
}
for (const key of needed) if (!available.has(key) && !textures.has(key)) missing.push(key);

const manifest = { generatedAt: new Date().toISOString(), packs: PACK_DIRS, models: [...available].sort() };
fs.mkdirSync(path.dirname(path.join(REPO_ROOT, "public", "assets", "manifest.json")), { recursive: true });
fs.writeFileSync(path.join(REPO_ROOT, "public", "assets", "manifest.json"), JSON.stringify(manifest, null, 1));

console.log(`assets: ${copied} copied, ${skipped} up to date, ${available.size} models available`);
if (missing.length) {
  console.error("layout references missing models:", missing.join(", "));
  process.exitCode = 1;
}
